We are interested in solving the linear inverse problem:
\begin{equation}   \label{eq:inverse_problem}
\text{find }\quad \xtrue \in \Xx \quad \text{s.t.}\quad A \xtrue = \ytrue,
\end{equation}
where $A: \mathcal{X}\to\mathcal{Y}$ is a bounded linear operator between two Hilbert spaces $\mathcal{X}$ and $\Yy$,
and $ \ytrue \in \mathcal{Y}$ can be seen as  a given  measurement of some unknown $\xtrue \in \Xx$ we want to recover.
In general, the inverse problem \eqref{eq:inverse_problem} is ill-posed as its solution (if it exists) may lack some fundamental properties like uniqueness or stability. 
A standard approach   is assuming the desired $\xtrue$ to be well-approximated by
 \cite{EngHanNeu96,BenBur18}:
\begin{equation}\label{eq:primal}
   \tag*{\textbf{($\bm{P_0(\ytrue)}$)}} \text{find\ }
      \xsol \in  \argmin  \left\{ R(x) \text{ s.t. } x\in\underset{x' \in \Xx}{\argmin}~ \ell(Ax';  \ytrue) \right\}, 
\end{equation} 
called the primal problem in the following.  Here,  $R$ is a  regularization function enforcing some \emph{a-priori} knowledge on  the desired solution $\xtrue$, while $\ell: \Yy^2\to\R\cup \{+\infty\}$ is a data-fit function. In practice, the  data  is  subject to noise  due to, e.g., possible transmission and/or acquisition problems. As a consequence, we only have access to an inexact version $\ynoisy$ of $\ytrue$. 


We begin fixing the  notation. Let $\Hh$ be a Hilbert space with scalar product  $\langle\cdot,\cdot\rangle$ and associated norm $\|\cdot\|$. Given $y\in\Hh$, and $\varrho\in\mathbb{R}_+$ and $\mathbb{B}(y,\varrho)$ is the open ball of center $y$ and radius $\varrho$.
we denote by $\Gamma_0(\Hh)$ the set of proper, convex and lower semi-continuous functions from $\Hh$ to $]-\infty,+\infty]$.
We say that  $f \in \Gamma_0(\Hh)$ is $\sigma$-{\em strongly convex}  if 
$f-{\sigma}\Vert \cdot \Vert^2/2 \in \Gamma_0(\Hh)$, with  $\sigma \in\left]0,+\infty\right[$.
We recall that the {\em subdifferential} of  $f \in \Gamma_0(\Hh)$  is the multi-valued operator 
$\partial f : \Hh \rightarrow 2^{\Hh}$ defined by setting
\begin{equation}  \label{def:subdiff}
(\forall x\in\Hh)\quad \partial f(x) := \left\{u \in \Hh: f(x') - f(x) - \langle u , x' - x \rangle \geq 0 \text{ for all } x' \in \Hh \right\}.
\end{equation}
Note that if $f$ is Gateaux differentiable at $x \in \Hh$, then $\partial f(x)=\{\nabla f(x) \}$, see, e.g.~, \cite[Proposition 17.31 i)]{BauschkeCombettes2017}.
We also recall that for all  $x\in \Hh$ and $\tau>0$ the proximity operator $\prox_{\tau f} : \Hh \rightarrow \Hh$  of $f\in\Gamma_0(\Hh)$ with parameter $\tau$ is defined by:
\begin{equation}\label{def:proximal operator}
    \prox_{\tau f}(x) =
    (I + \partial f)^{-1}(x) = 
    \argmin\limits_{x' \in \Hh} \left\{ f(x') + \frac{1}{2\tau}\Vert x' - x \Vert^2 \right\}.
\end{equation}
Given $f \in \Gamma_0(\Hh)$, we will denote by $f^* : \Hh \rightarrow [-\infty,+\infty]$   the {\em Fenchel conjugate} of $f$
\[
(\forall u\in\Hh)\quad f^*(u):=  \sup_{x\in \Hh}  \left\{\langle u,x\rangle_{\Hh} -f(x) \right\}.
\]
The Fenchel conjugate of $f$ belongs to $\Gamma_0(\Hh)$, and if $f$ is $\sigma$-strongly convex then $f^*$ is differentiable at any point, with a $\sigma^{-1}$-Lipschitz continuous gradient, see, e.g. \cite[Theorem 18.15]{BauschkeCombettes2017}. 
Furthermore, the following property holds, see \cite[Theorem 16.23]{BauschkeCombettes2017}: 
\[
(\forall (x,u)\in \Hh^2)\quad u \in \partial f(x) \Leftrightarrow x \in \partial f^*(u).
\] 
Finally, given two real sequences $(a_k)_{k\geq 1}$ and $(b_k)_{k\geq 1}$, we will write $a_k = O(b_k)$ whenever there exists a positive constant $M>0$ such that $a_k \leq M b_k$ for all $k \geq 1$. We will use the more precise notation $a_k = \Theta(b_k)$ if both conditions $a_k = O(b_k)$ and $b_k = O(a_k)$ hold.
Note also that we will use the same notation  $\|\cdot\|$ and $\langle\cdot,\cdot\rangle$ for the norm and the scalar product in every Hilbert space we consider. 


We make   the following assumptions on the data-fit $\ell$ and the regularizer $R$: 
\begin{enumerate}[label=\textbf{$(L_\arabic*)$}]
	\item \label{assumption:data-fit convex and coercive}
	For all $y \in \Yy$, $\ell_y:=\ell(\cdot,y)\in \Gamma_0(\Yy) $ and it is coercive.
	\item \label{assumption:data-fit not flat} 
	For all $(y_1,y_2)\in \Yy^2, ~\ell(y_1,y_2)=0 \iff y_1=y_2$.
	\item \label{assumption:data-fit conditionned locally}
	 there exists
     $q\in[1,+\infty[$, $\varrho \in ]0,+\infty]$, $ \gamma \in ]0,+\infty[$ such that
	$$
	\forall y \in \mathbb{B}( \ytrue,\varrho),\quad \frac{\gamma}{q}\Vert y-\ytrue\Vert^q \leq \ell(y,\ytrue). 
	$$ 
\end{enumerate}
\begin{enumerate}[label=\textbf{$(R_\arabic*)$}]	
	\item \label{H:R strongly convex} $R$ is $\sigma$-strongly convex, with $\sigma \in \left]0,+\infty\right[$,  
	\item \label{assumption:AR2}   $\partial R(\xsol) \cap \im A^* \neq \emptyset$.	
\end{enumerate}
If assumption \ref{assumption:data-fit conditionned locally} is satisfied, we say that $\ell_{\ytrue}$ is \emph{locally
	$q$-conditioned} at $\bar{y}$. If \ref{assumption:data-fit conditionned locally} is satisfied with $\rho=+\infty$, then we say that $\ell_{\ytrue}$  is $q$-conditioned at $\bar{y}$.


A class of methods to solve \eqref{eq:inverse_problem}  consider the   problem 
\begin{equation}   \label{eq:primal_char}
    \text{find }  \xsol \in  \argmin_{x \in \Xx}  \left\{ R(x) + \delta_{\bar{y}}(Ax) \right\},
\end{equation}
where the constraint \eqref{eq:inverse_problem} is encoded by the indicator function $\delta_{\bar{y}}$. Using Fenchel-Rockafeller duality,  
we derive the corresponding dual problem:
\begin{equation}   \label{eq:Dual}
\text{find } u^\dagger \quad\text{ s.t. }\quad u^\dagger \in \argmin_{u\in \mathcal{Y}}\  \left\{ d_0(u) := R^*(-A^*u) + \langle \bar{y}, u \rangle \right\}
    \tag*{\textbf{($\bm{D_0}$)}}.
\end{equation}


The dual problem of \ref{eq:primal penalized} is
\begin{equation}   \label{eq:DualReg}
\text{find } u_\lambda \in \argmin_{u\in \mathcal{Y}}\ \left\{d_\lambda(u) := R^*(-A^*u) + \frac{1}{\lambda}\ell^*(\lambda u;\ynoisy)\right\}.   \tag*{\textbf{($\bm{D_\lambda}$)}}
\end{equation} 


\begin{equation}\label{alg:fw_accel}
u_0 = u_1 \in \Yy, \quad \text{ compute for } k \geq 1 \quad 
\begin{cases}
 w_k & = u_k + \alpha_k(u_k-u_{k-1}), \\
 u_{k+1} &= \mathrm{prox}_{\frac{\tau}{\lambda_{k}} \ell^*_{\bar{y}}(\lambda_k\cdot)}\left(w_k - \tau\nabla \RA(w_k)\right),\\
    x_{k+1} & = \nabla R^*(-A^* u_{k+1}). 
\end{cases}
\tag*{\textbf{($\bm{I3D}$)}}
\end{equation}
This algorithm depends on three parameters: the stepsize $\tau >0$, the relaxation parameters $(\lambda_k)_k$ and the friction parameters $(\alpha_k)_k$.
The stepsize will be chosen depending on the value of the Lipschitz constant of $\nabla \RA$.
For the relaxation parameters, we will consider a discrete analogue of the assumption \ref{requirement:lambda1:cont} formulated in the continuous setting.
For the friction parameters $\alpha_k$, we will allow more general values not necessarily corresponding to $\alpha_k = 1 -\alpha/k$ as  above. We gather  the requirements on the   parameters in the following assumptions:
\begin{enumerate}[label=\textbf{$(P_\arabic*)$}]
	\item \label{assumption:parameter:stepsize}
	$\tau \in \left(0,\frac{\sigma^2}{\Vert A \Vert^2}\right]$, where $\sigma > 0$ is defined in assumption \ref{H:R strongly convex}.
	\item \label{assumption:parameter:friction}
	$\alpha_k$ is non-negative and for every $k\geq 1$, $t_k:=1+\sum_{i=k}^{+\infty}\prod_{j=k}^i \alpha_j$ is finite,  with $t_k = \Theta(k)$.
	\item \label{assumption:parameter:relaxation}
	$(\lambda_k)$ is a strictly positive non-increasing sequence such that $\lim_{k\to\infty} \lambda_k = 0$. 
	Moreover, by defining
	\begin{equation}   \label{def:biglambda}
	\Lambda:=
	\begin{cases}
	\sum_{k\geq 1} t_{k+1} \lambda_k^{1/(q-1)}
	& \text{ if } q>1, \\
	0
	& \text{ if } q=1, 
	\end{cases}
	\end{equation}
	we have that $\Lambda< + \infty$.
	\item \label{assumption:parameter:technical}
	For some $u^\dagger \in \argmin d_0$, we have  $\lambda_0 \Vert u^\dagger \Vert \leq \gamma \varrho^{q-1} /q$.
\end{enumerate}


 Following \cite{AttouchTikAccel}, we require the sequence of friction parameters $(\alpha_k)$ to satisfy  \ref{assumption:parameter:friction},  a particular summability property  guaranteeing a technical condition crucial in the following. We summarize such a requirement and the resulting condition in the following lemma.

\begin{lemma}[ {{\cite[Lemma 2.1]{AttouchTikAccel} }}]   \label{lemma:sequence}
Assume that $(\alpha_k)$ is non-negative and satisfies
\begin{equation}  \label{eq:choice:alpha}
\sum_{i=k}^{+\infty}\prod_{j=k}^i \alpha_j<+\infty,\quad\text{for every }k\geq 1.
\end{equation}
Then, the sequence defined by
\begin{equation} \label{eq:choice:tk}
t_k:=1+\sum_{i=k}^{+\infty}\prod_{j=k}^i \alpha_j
\end{equation}
is well-defined, and satisfies for every $k\geq 1$ the following properties:
\begin{equation}   \label{eq:properties_sequences_alphak_tk}
1+\alpha_k t_{k+1} = t_k, \qquad t^2_{k+1}-t^2_k\leq t_{k+1}.
\end{equation}
\end{lemma}


We first consider $\Rr_A $, $\ell^*_y$ defined in \eqref{eq:composite} and on the diagonal dual function $d_{\lambda}$ and its limit $d_0$  defined in \ref{eq:DualReg} and \ref{eq:Dual}, respectively. For similar results see also \cite{Garrigos2017}.

