\begin{theorem}[Fast convergence]\label{T:discrete convergence rates noiseless}
Let the assumptions \ref{assumption:data-fit convex and coercive}-\ref{assumption:data-fit conditionned locally}, \ref{H:R strongly convex}-\ref{assumption:AR2}, \ref{assumption:parameter:stepsize}-\ref{assumption:parameter:technical} hold true.
Let $(x_k)$ and $(u_k)$ be the sequences generated by algorithm \ref{alg:fw_accel}.
Then, there exists $C\in\left]0,+\infty\right[$ such that
\begin{equation}  \label{eq:rate}%\label{eq:rate:primal:it}
 d_{{\lambda_k}}(u_k) - \inf  d_0  \leq \frac{C}{t_k^2} 
 \quad \text{ and } \quad 
 \| x_k - x^\dagger \| \leq \frac{\sqrt{2C}}{\sqrt{\sigma}t_k}.
\end{equation}
\end{theorem}

proof.raw_tex:
\begin{proof}
Let $u^\dagger\in \argmin d_0$ be the minimizer of $d_0$ defined in assumption \ref{assumption:parameter:technical}, and
define, for every $k\geq 1$,  the discrete Lyapunov energy function:
\begin{equation}  \label{eq:discrete energy}
\mathcal{E}(k):=t_k^2 \Big( d_{{\lambda_k}}(u_k)-\inf d_0\Big) + \frac{1}{2\tau}\|z_k-u^\dagger\|^2,
\end{equation}
where $z_k$ is defined as:
\begin{equation}  \label{eq:def_zk:noisefree}
z_k:=u_{k-1} +t_k(u_k-u_{k-1}).
\end{equation}
Our goal is to get an estimate on the decay of $\mathcal{E}$ along time.
More precisely, we will show that for every $k\geq 1$
\begin{equation}  \label{eq:condition}
\mathcal{E}(k+1) - \mathcal{E}(k)
\leq  t_{k+1} \Big(d_{{\lambda_k}}(u^\dagger) -  \inf d_0\Big),
\end{equation}
which can be seen as a discrete analogue of \eqref{proof:ccd2}, and from which the desired accelerated convergence rates will follow in a straightforward manner.

For simplicity, let us denote by $\ell_k$  the function defined by setting
\begin{equation}  \label{eq:shortand_notation_Dk}
(\forall u\in \mathcal{Y})\quad \ell_k(u)=\lambda_k^{-1}{\ell}_{\bar{y}}^*(\lambda_k u).
\end{equation} 
To prove \eqref{eq:condition}, we define for every $k\geq 1$ the operator $G_k:\mathcal{Y}\to \mathcal{Y}$ as
\begin{equation}  \label{eq:fw_operator}
G_k(z)  := \frac{1}{\tau}\Big(z-\text{prox}_{\tau \ell_k}(z-\tau \nabla  \RA(z))\Big)
\end{equation}
and notice that the proximal step of  \ref{alg:fw_accel} can be written in terms of $G_k$ as $u_{k+1}=w_k - \tau G_k(w_k)$. The descent lemma yields (see, e.g., \cite{AttouchTikAccel,ChambolleDossal2015})
\begin{equation}  \label{eq:descent}
    d_{\lambda_k}(w-\tau G_k(w)) \leq  d_{\lambda_k}(u) + \langle G_k(w), w-u\rangle - \frac{\tau}{2}\|G_k(w)\|^2, \quad \text{for all }w,u\in\mathcal{Y},
\end{equation}
Evaluating \eqref{eq:descent} for $u=u_{k}$ and $w=w_k$, we get
\begin{equation}  \label{descent:first}
d_{{\lambda_k}}(u_{k+1}) \leq  d_{{\lambda_k}}(u_{k}) + \langle G_k(w_k), w_k - u_{k}\rangle - \frac{\tau}{2}\|G_k(w_k)\|^2.
\end{equation}
Evaluating \eqref{eq:descent} for $u=u^\dagger$ and $w=w_k$ we derive
 \begin{equation}  \label{descent:second}
d_{{\lambda_k}}(u_{k+1}) \leq  d_{{\lambda_k}}(u^\dagger) + \langle G_k(w_k), w_k -u^\dagger\rangle - \frac{\tau}{2}\|G_k(w_k)\|^2.
\end{equation}
We now multiply \eqref{descent:first} by $t_{k+1}-1$ and we add it to \eqref{descent:second}, and we obtain
\begin{align}
t_{k+1} d_{{\lambda_k}}(u_{k+1}) 
&\leq  (t_{k+1}-1)d_{{\lambda_k}}(u_{k}) +  d_{{\lambda_k}}(u^\dagger)  \nonumber\\
\label{ineq:1}&+ \langle  G_k(w_k), (t_{k+1}-1)(w_k-u_{k}) + (w_{k} - u^\dagger)\rangle  -\frac{\tau}{2}t_{k+1}\|  G_k(w_k)\|^2 . 
\end{align}
As an immediate consequence of Lemma \ref{lemma:sequence}, we observe the following property:
\begin{align}  \label{eq:property_zk}
(t_{k+1}-1)(w_k-u_{k}) + w_k & = u_{k} + t_{k+1}(w_k -u_{k}) \notag\\
& = u_{k} + t_{k+1} \alpha_k(u_{k} -u_{k-1}) \\
& = u_{k-1} + (1+ t_{k+1} \alpha_k)(u_{k} -u_{k-1}) \notag\\
& = u_{k-1} +t_k(u_{k} -u_{k-1}) = z_k. \notag
\end{align}
Thanks to \eqref{eq:def_zk:noisefree}, the fact that $z_k-\tau t_{k+1}G_k(w_k)=z_{k+1}$ and the previous equality, we can reorder the terms in \eqref{ineq:1} and rewrite it as
\begin{align}
t_{k+1} ( d_{{\lambda_k}}(u_{k+1}) -  d_{{\lambda_k}}(u^\dagger)) 
& \leq  (t_{k+1}-1) (d_{{\lambda_k}}(u_{k}) -  d_{{\lambda_k}}(u^\dagger)) \notag\\
& + \frac{1}{2\tau t_{k+1}}\left(\|z_{k}-u^\dagger\|^2-\|z_{k+1}-u^\dagger\|^2\right). \notag 
\end{align}
We now multiply everything by $t_{k+1}$, re-arrange and get
\begin{align}  \label{descent:third}
& t^2_{k+1} ( d_{{\lambda_k}}(u_{k+1}) -  d_{{\lambda_k}}(u^\dagger))   + \frac{1}{2\tau}
\|z_{k+1}-u^\dagger\|^2   \\
&\leq  (t^2_{k+1}-t_{k+1}) (d_{{\lambda_k}}(u_{k}) -  d_{\lambda_k}(u^\dagger)) + \frac{1}{2\tau } \|z_{k}-u^\dagger\|^2.  \notag
\end{align}
Equivalently:
\begin{align}  \label{descent:third2}
& t^2_{k+1} \Big( d_{{\lambda_k}}(u_{k+1}) -  d_{{\lambda_k}}(u^\dagger) \Big)   + \frac{1}{2\tau}
\|z_{k+1}-u^\dagger\|^2 \nonumber  \\
&\leq  t^2_k \Big(d_{{\lambda_k}}(u_{k}) -  d_{{\lambda_k}}(u^\dagger)\Big) +   (t^2_{k+1}-t_{k+1} - t_{k}^2) \Big( d_{{\lambda_k}}(u_{k}) -  d_{{\lambda_k}}(u^\dagger) \Big)+ \frac{1}{2\tau } \|z_{k}-u^\dagger\|^2. \notag
\end{align}
To get the desired terms, we first use on the left-hand side  the monotonicity property of the function $ d_{{\lambda_k}}(\cdot)$ as a function of $k$ (see  Lemma  \ref{L:functional properties}\ref{L:functional properties:decreasing function sequence}) and then add and subtract in the parentheses  the term $\inf d_0$, thus getting:
\begin{align}  \label{descent:fifth}
&t^2_{k+1} \Big( d_{{\lambda_{k+1}}}(u_{k+1}) -   \inf d_0 \Big)   + \frac{1}{2\tau}
\|z_{k+1}-u^\dagger\|^2   \notag \\
&\leq  t^2_k \Big(d_{{\lambda_{k}}}(u_{k}) - \inf d_0 \Big) +   (t^2_{k+1}-t_{k+1} - t_{k}^2) \Big( d_{{\lambda_{k}}}(u_{k}) -  \inf d_0\Big) \\
& +t_{k+1} \Big(d_{{\lambda_{k}}}(u^\dagger) -  \inf d_0\Big)   +  \frac{1}{2\tau } \|z_{k}-u^\dagger\|^2. \notag
\end{align}
After rearranging and using the definition of $\mathcal{E}$ in \eqref{eq:discrete energy}, we deduce:
\begin{align}  \label{descent:fifth}
\mathcal{E}(k+1) +    (t^2_{k}+t_{k+1} - t_{k+1}^2) \Big( d_{{\lambda_{k}}}(u_{k}) -  \inf d_0\Big) \leq  \mathcal{E}(k) + t_{k+1} \Big(d_{{\lambda_{k}}}(u^\dagger) -  \inf d_0\Big). \nonumber
\end{align}

\noindent Thanks to \eqref{eq:properties_sequences_alphak_tk} and  Lemma~\ref{L:functional properties}\ref{L:functional properties:decreasing function sequence}, we can neglect the second term  in the left-hand side of the above inequality,  finally getting the desired  \eqref{eq:condition}.
Iterating \eqref{eq:condition}  recursively gives
\begin{align}  \label{eq:decay_complete}
\mathcal{E}(k) \leq \mathcal{E}(1) +\sum_{j=1}^{k-1}t_{j+1}\Big( d_{\lambda_{j}}(u^\dagger)-\inf d_0 \Big).
\end{align}
To  bound the sum appearing on the right hand side, we need to analyze the residuals $r_j:= d_{\lambda_{j}}(u^\dagger) -\inf d_0$. Similarly as for the estimation obtained in the continuous case, we can use for this purpose the property in Lemma \ref{L:functional properties}\ref{L:functional properties:diagonal rates via conditioning} and get that for some fixed constant $c$ independent on $j$ (defined analogously as in \eqref{proof:ccd3}), we have
$$
r_j\leq c \lambda_j^{\frac{1}{q-1}},\qquad\text{for every }j\geq 1.
$$
By assumption \ref{assumption:parameter:relaxation}, with $\Lambda$ as  in \eqref{def:biglambda}, we thus conclude that
$$
\sum_{j=1}^{k-1} t_{j+1} r_j \leq  c \sum_{j=1}^{k-1} t_{j+1} \lambda_j^{\frac{1}{q-1}}  \leq c \Lambda < +\infty
$$
This allows us to deduce from \eqref{eq:decay_complete} the convergence rate on the dual values in \eqref{eq:rate}, by taking $C = \Ee(1) + c \Lambda$.
Finally, the convergence rate on the primal iterates  in \eqref{eq:rate} follows from  Lemma \ref{L:functional properties}\ref{L:functional properties:from dual value to primal iterates}.
\end{proof}

\begin{lemma}\label{L:functional properties}
Under the assumptions \ref{assumption:data-fit convex and coercive}-\ref{assumption:data-fit conditionned locally} and \ref{H:R strongly convex}-\ref{assumption:AR2},  we have:
\begin{enumerate}[label=(\roman*)]
	\item\label{L:functional properties:R_A Lipschitz} $\Rr_A$ is differentiable and $\nabla  \RA$ is Lipschitz continuous, with Lipschitz constant equal to $\sigma^{-1} \Vert A \Vert^2$.
	\item\label{L:functional properties:L at 0} $\forall y \in \Yy$, $\ell^*_{y}(0)=0$ and $\partial \ell^*_y(0)=\{y\}$.
	\item\label{L:functional properties:argmin d_0 nonempty} There holds: $\argmin  d_0 \neq \emptyset$.
 	\item\label{L:functional properties:decreasing function sequence} $\forall u \in \Yy$, the function $\lambda\in [0,+\infty) \mapsto \ d_{\lambda}(u)$ is nondecreasing. 
	\item\label{L:functional properties:from dual value to primal iterates} $\forall t >0, \forall u \in \Yy, \ \text{ if }
{x}:=\nabla R^*(-A^*u),$ then $
 \frac{\sigma}{2} \Vert {x} - x^\dagger \Vert^2 \leq d_0(u) - \inf d_0.$ 
 	\item\label{L:functional properties:diagonal rates via conditioning} $\forall u^\dagger \in \argmin  d_0$, if  $\lambda \Vert u^\dagger \Vert \leq \frac{\gamma}{q} \varrho^{q-1}$, then
 	\begin{equation}
 	    d_{\lambda}(u^\dagger) - \inf  d_0 \leq
 	    \begin{cases}
 	     0 & \text{ if } q=1, \\
 	     (1-\frac{1}{q}) {\gamma^{-1/(q-1)}} \Vert u^\dagger \Vert^{q/(q-1)} \lambda^{1/(q-1)} & \text{ if } q>1.
 	    \end{cases}
 	\end{equation}
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{L:functional properties:R_A Lipschitz}: follows  from the strong convexity of $R$, see, e.g.,  
\cite[Theorem 18.15]{BauschkeCombettes2017}.\\
\ref{L:functional properties:L at 0}: it is a simple consequence of the properties of the Fenchel transform as it can be found, e.g., in 
 \cite[Proposition 13.10(i) \& Corollary 16.30]{BauschkeCombettes2017}.\\
\ref{L:functional properties:argmin d_0 nonempty} and \ref{L:functional properties:from dual value to primal iterates}: follow from \cite[Lemma 5]{Garrigos2017} by simply taking $f=R$ and $g=\delta_{\{\bar y\}}$, while property \ref{L:functional properties:decreasing function sequence} has been proved in \cite[Proposition 2(i)]{Garrigos2017}.\\
\ref{L:functional properties:diagonal rates via conditioning}: it is enough to verify that $\ell_{\bar y}(\cdot)$ is $q$-well conditioned in the sense of \cite[Definition 1]{Garrigos2017}, while assumption \ref{assumption:data-fit conditionned locally} holds only locally.
To check this, we introduce the function $\psi : \R \rightarrow \R$ defined for the $\varrho>0$ appearing in \ref{assumption:data-fit conditionned locally}  by:
\begin{equation}
 \psi  t \mapsto
\begin{cases}
 \frac{\gamma}{q}\vert t \vert^q  & \text{ if } \vert t \vert \leq \varrho, \\
 \frac{\gamma}{q} \varrho^{q-1} \vert t \vert & \text{ if } \vert t \vert > \varrho.
\end{cases}
\end{equation}
From \ref{assumption:data-fit conditionned locally}, we easily  deduce that $\ell_{\bar y}(y) \geq \psi(\Vert y- \bar y \Vert)$ for all $y \in \Yy$ (see \cite[Corollary 3.4.2]{ZalinescuBook2002}).
Note that $\psi$ is not convex for $q >1$, so in this case we consider instead the function
\begin{equation}
 m: \R \rightarrow \R , \quad t \mapsto 
\begin{cases}
 \frac{\gamma}{q}\vert t \vert^q  & \text{ if } \vert t \vert \leq q^{1/(1-q)} \varrho, \\
 \frac{\gamma}{q}\varrho^{q-1}\vert t \vert 
 -  \frac{\gamma}{q^{\frac{q}{q-1}}}\varrho^q (1 - \frac{1}{q})  & \text{ if } \vert t \vert > q^{1/(1-q)} \varrho,
\end{cases}
\end{equation}
and define $m:=\psi$ for $q=1$.
It is an easy exercise to verify that $m$ is indeed a convex function on $\R$, and that $m(w) \leq \psi(w)$ for all $w\in\R$.
Now, we can make use of \cite[Lemma 2]{Garrigos2017},
which tells us that $d_\lambda(u) - \inf d_0 \leq \lambda^{-1} m^*(\Vert u \Vert \lambda)$.
The desired result  now follows from the computation of the Fenchel transform of $m$.
If $q=1$, we have that $m(t) = \gamma \vert t \vert$, so classic Fenchel calculus entails that $m^*$ is $\delta_{[-\gamma,\gamma]}$, the indicator function of $[-\gamma,\gamma]$.
If $q>1$, easy computations show that $m^*$ reads
\begin{equation}
