\begin{cases}
 (1 - \frac{1}{q}) \gamma^{-1/(q-1)}\vert s \vert^{\frac{q}{q-1}}  & \text{ if } \vert s \vert \leq \frac{\gamma}{q} \varrho^{q-1}, \\
 + \infty  & \text{ if } \vert s \vert > \frac{\gamma}{q} \varrho^{q-1}.
\end{cases}
\end{equation}
By now applying \cite[Lemma 2]{Garrigos2017} we  conclude. 
\end{proof}

