A standard approach   is assuming the desired $\xtrue$ to be well-approximated by
 \cite{EngHanNeu96,BenBur18}:
\begin{equation}\label{eq:primal}
   \tag*{\textbf{($\bm{P_0(\ytrue)}$)}} \text{find\ }
      \xsol \in  \argmin  \left\{ R(x) \text{ s.t. } x\in\underset{x' \in \Xx}{\argmin}~ \ell(Ax';  \ytrue) \right\}, 
\end{equation} 
called the primal problem in the following.  Here,  $R$ is a  regularization function enforcing some \emph{a-priori} knowledge on  the desired solution $\xtrue$, while $\ell: \Yy^2\to\R\cup \{+\infty\}$ is a data-fit function. In practice, the  data  is  subject to noise  due to, e.g., possible transmission and/or acquisition problems. As a consequence, we only have access to an inexact version $\ynoisy$ of $\ytrue$.

We recall that the {\em subdifferential} of  $f \in \Gamma_0(\Hh)$  is the multi-valued operator 
$\partial f : \Hh \rightarrow 2^{\Hh}$ defined by setting
\begin{equation}  \label{def:subdiff}
(\forall x\in\Hh)\quad \partial f(x) := \left\{u \in \Hh: f(x') - f(x) - \langle u , x' - x \rangle \geq 0 \text{ for all } x' \in \Hh \right\}.
\end{equation}
Note that if $f$ is Gateaux differentiable at $x \in \Hh$, then $\partial f(x)=\{\nabla f(x) \}$, see, e.g.~, \cite[Proposition 17.31 i)]{BauschkeCombettes2017}.

We also recall that for all  $x\in \Hh$ and $\tau>0$ the proximity operator $\prox_{\tau f} : \Hh \rightarrow \Hh$  of $f\in\Gamma_0(\Hh)$ with parameter $\tau$ is defined by:
\begin{equation}\label{def:proximal operator}
    \prox_{\tau f}(x) =
    (I + \partial f)^{-1}(x) = 
    \argmin\limits_{x' \in \Hh} \left\{ f(x') + \frac{1}{2\tau}\Vert x' - x \Vert^2 \right\}.
\end{equation}

A class of methods to solve \eqref{eq:inverse_problem}  consider the   problem 
\begin{equation}   \label{eq:primal_char}
    \text{find }  \xsol \in  \argmin_{x \in \Xx}  \left\{ R(x) + \delta_{\bar{y}}(Ax) \right\},
\end{equation}
where the constraint \eqref{eq:inverse_problem} is encoded by the indicator function $\delta_{\bar{y}}$. Using Fenchel-Rockafeller duality,

where the constraint \eqref{eq:inverse_problem} is encoded by the indicator function $\delta_{\bar{y}}$. Using Fenchel-Rockafeller duality,  
we derive the corresponding dual problem:
\begin{equation}   \label{eq:Dual}
\text{find } u^\dagger \quad\text{ s.t. }\quad u^\dagger \in \argmin_{u\in \mathcal{Y}}\  \left\{ d_0(u) := R^*(-A^*u) + \langle \bar{y}, u \rangle \right\}
    \tag*{\textbf{($\bm{D_0}$)}}.
\end{equation}

The dual problem of \ref{eq:primal penalized} is
\begin{equation}   \label{eq:DualReg}
\text{find } u_\lambda \in \argmin_{u\in \mathcal{Y}}\ \left\{d_\lambda(u) := R^*(-A^*u) + \frac{1}{\lambda}\ell^*(\lambda u;\ynoisy)\right\}.   \tag*{\textbf{($\bm{D_\lambda}$)}}
\end{equation}

From now on we will use the following shorthand notation: 
\begin{equation} \label{eq:composite}
   \RA: = R^* \circ (-A^*),\qquad \ell^*_{\bar{y}}(\cdot): = \ell(\cdot,\bar{y})^*
\end{equation}
so that the composite dual function $d_\lambda$ can be written as $d_{\lambda}(u) =  \RA(u) + \lambda^{-1} \ell^*_{\bar{y}}(\lambda u)$, for every $u\in\mathcal{Y}$.

where the constant $c$ is defined as:
\begin{equation}\label{proof:ccd3}
    c :=
    \begin{cases}
    0 \quad &\quad \text{ if }q=1,\\
    (1-(1/q))\gamma^{-1/(q-1)}\Vert u^\dagger \Vert^{q/(q-1)} \quad &\quad \text{ if } q >1,
    \end{cases}
\end{equation}
and it is finite in both cases.

\begin{equation}\label{alg:fw_accel}
u_0 = u_1 \in \Yy, \quad \text{ compute for } k \geq 1 \quad 
\begin{cases}
 w_k & = u_k + \alpha_k(u_k-u_{k-1}), \\
 u_{k+1} &= \mathrm{prox}_{\frac{\tau}{\lambda_{k}} \ell^*_{\bar{y}}(\lambda_k\cdot)}\left(w_k - \tau\nabla \RA(w_k)\right),\\
    x_{k+1} & = \nabla R^*(-A^* u_{k+1}). 
\end{cases}
\tag*{\textbf{($\bm{I3D}$)}}
\end{equation}
This algorithm depends on three parameters: the stepsize $\tau >0$, the relaxation parameters $(\lambda_k)_k$ and the friction parameters $(\alpha_k)_k$.

\item \label{assumption:parameter:relaxation}
$(\lambda_k)$ is a strictly positive non-increasing sequence such that $\lim_{k\to\infty} \lambda_k = 0$. 
Moreover, by defining
\begin{equation}   \label{def:biglambda}
\Lambda:=
\begin{cases}
\sum_{k\geq 1} t_{k+1} \lambda_k^{1/(q-1)}
& \text{ if } q>1, \\
0
& \text{ if } q=1, 
\end{cases}
\end{equation}
we have that $\Lambda< + \infty$.

	\item \label{assumption:parameter:technical}
	For some $u^\dagger \in \argmin d_0$, we have  $\lambda_0 \Vert u^\dagger \Vert \leq \gamma \varrho^{q-1} /q$.
\end{enumerate}

\begin{lemma}[ {{\cite[Lemma 2.1]{AttouchTikAccel} }}]   \label{lemma:sequence}
Assume that $(\alpha_k)$ is non-negative and satisfies
\begin{equation}  \label{eq:choice:alpha}
\sum_{i=k}^{+\infty}\prod_{j=k}^i \alpha_j<+\infty,\quad\text{for every }k\geq 1.
\end{equation}
Then, the sequence defined by
\begin{equation} \label{eq:choice:tk}
t_k:=1+\sum_{i=k}^{+\infty}\prod_{j=k}^i \alpha_j
\end{equation}
is well-defined, and satisfies for every $k\geq 1$ the following properties:
\begin{equation}   \label{eq:properties_sequences_alphak_tk}
1+\alpha_k t_{k+1} = t_k, \qquad t^2_{k+1}-t^2_k\leq t_{k+1}.
\end{equation}
\end{lemma}

